#include <stdio.h>
#include <stdlib.h>

#define MAX_ELEMS 64

int main(int argc, char **argv) {
    long value[MAX_ELEMS];
    int next[MAX_ELEMS];
    int head = -1;
    int used = 0;
    for (int i = 1; i < argc && used < MAX_ELEMS; ++i) {
        long v = strtol(argv[i], NULL, 10);
        int idx = used++;
        value[idx] = v;
        next[idx] = -1;
        if (head == -1 || value[head] > v) {
            next[idx] = head;
            head = idx;
        } else {
            int cur = head;
            while (next[cur] != -1 && value[next[cur]] <= v) {
                cur = next[cur];
            }
            next[idx] = next[cur];
            next[cur] = idx;
        }
    }
    if (head == -1) {
        puts("EMPTY");
        return 0;
    }
    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) putchar(' ');
        printf("%ld", value[cur]);
        first = 0;
        cur = next[cur];
    }
    putchar('\n');
    return 0;
}
